[
  {
    "beat_id": "post_fall_3_days",
    "scene": "Mraka is fiddling with a small device, Tarven observes from his archive station.",
    "exchanges": [
      {"speaker": "Mraka", "line": "This micro-resonator… it’s just not responding. Tools are alphabetized, you know. Every single one."},
      {"speaker": "Tarven", "line": "Indeed. The records are useful, Mraka. Perhaps you are attempting to recalibrate a dampener with a flux coil? It is a common error."},
      {"speaker": "Mraka", "line": "A common error is assuming I make common errors. It's the coupling. It needs… a certain *feel*."},
      {"speaker": "Tarven", "line": "A feel that the records do not detail, I presume. Fascinating. My own analysis suggests thermal variance."}
    ]
  },
  {
    "beat_id": "post_fall_3_weeks",
    "scene": "Sevra is reading to Vresh-Hum-Of-The-Slow-Veins, who is humming a subdued pattern. Renn is nearby, ostensibly cleaning.",
    "exchanges": [
      {"speaker": "Sevra", "line": "‘…and the starlight, once a comforting blanket, now seemed to stretch thin, brittle.’"},
      {"speaker": "Vresh-Hum-Of-The-Slow-Veins", "line": "We-all feel the… stretch. The brittleness. It resonates."},
      {"speaker": "Renn", "line": "Yeah, that… that feeling. Like the whole ship’s hum is a little… off. Off-key, you know? Not groovy at all."},
      {"speaker": "Sevra", "line": "We will find the right key again, Renn. Tomorrow, perhaps."}
    ]
  },
  {
    "beat_id": "post_fall_1_month",
    "scene": "Forward is watching the main display, a slight ripple of his ribbon-body. Forty-Seven's presence is subtly noted.",
    "exchanges": [
      {"speaker": "Forward", "line": "The sensor sweep indicates a 0.003% increase in ambient nebula density. Facing forward, this presents a marginal tactical consideration."},
      {"speaker": "Forty-Seven", "line": "By my standards, that is a statistically significant deviation from baseline. I am cross-referencing with historical atmospheric models."},
      {"speaker": "Mraka", "line": "Deviation means something changed. Always something changing. Keeps things… interesting, I guess."},
      {"speaker": "Tarven", "line": "The records indicate many changes, Mraka. Some are more… impactful than others. The present era is certainly marked by impact."}
    ]
  }
]
